import { path } from '@servicenow/sdk-build-core'
import { createTestContext, getMergedRecordUpdates, unzipInputArray } from '../test-utils'

/**
 * Comprehensive test suite for inline scripts in flow logic (setFlowVariables and assignSubflowOutputs)
 *
 * Tests cover:
 * - flow-logics/fluent to XML conversion (simple and complex cases)
 * - XML to flow-logics/fluent conversion (bidirectionality)
 * - Proper isolation between inline scripts and datapills
 * - Correct scriptActive flag and structure
 */
describe('Flow Logic Inline Scripts Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('SetFlowVariables with Inline Scripts - flow-logics/fluent to XML', () => {
        /**
         * TEST 1: Simple Case
         * Tests basic inline script functionality without datapills
         * Verifies:
         * - Inline scripts are detected and converted
         * - scriptActive flag is set to true
         * - Script content is preserved
         * - Proper JSON structure in variables array
         */
        test('SetFlowVariables with simple inline scripts', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'set-flow-variables-inline-script-simple.now.ts',
                'flow-logics/fluent'
            )

            // Verify flow logic instance was created
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            expect(flowLogicInstances.length).toBeGreaterThan(0)

            // Find the SetFlowVariables instance
            const setFlowVarsInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set variables with simple inline scripts'
            )
            expect(setFlowVarsInstance).toBeDefined()

            // Parse the gzipped values
            const valuesJson = unzipInputArray(setFlowVarsInstance.values) as any

            // Verify 'variables' array exists
            expect(valuesJson.variables).toBeDefined()
            expect(valuesJson.variables.length).toBe(3) // greeting, timestamp, randomNumber

            // Test 1.1: Verify greeting inline script
            const greetingVar = valuesJson.variables.find((v: any) => v.name === 'greeting')
            expect(greetingVar).toBeDefined()
            expect(greetingVar.scriptActive).toBe(true)
            expect(greetingVar.script).toBeDefined()
            expect(greetingVar.script.greeting).toBeDefined()
            expect(greetingVar.script.greeting.scriptActive).toBe(true)
            expect(greetingVar.script.greeting.script).toContain("return 'Hello from inline script!'")

            // Test 1.2: Verify timestamp inline script
            const timestampVar = valuesJson.variables.find((v: any) => v.name === 'timestamp')
            expect(timestampVar).toBeDefined()
            expect(timestampVar.scriptActive).toBe(true)
            expect(timestampVar.script).toBeDefined()
            expect(timestampVar.script.timestamp.script).toContain('new Date().toISOString()')

            // Test 1.3: Verify randomNumber inline script
            const randomVar = valuesJson.variables.find((v: any) => v.name === 'randomNumber')
            expect(randomVar).toBeDefined()
            expect(randomVar.scriptActive).toBe(true)
            expect(randomVar.script.randomNumber.script).toContain('Math.floor')
            expect(randomVar.script.randomNumber.script).toContain('Math.random()')

            // Test 1.4: Verify all inline scripts have empty value and displayValue
            valuesJson.variables.forEach((v: any) => {
                expect(v.value).toBe('')
                expect(v.displayValue).toBe('')
            })

            // Test 1.5: Verify inputs array also exists (backward compatibility)
            expect(valuesJson.inputs).toBeDefined()
            expect(valuesJson.inputs.length).toBe(valuesJson.variables.length)
        })

        /**
         * TEST 2: Complex Case with Datapills
         * Tests that inline scripts and datapills can coexist without interference
         * Verifies:
         * - Inline scripts are processed correctly
         * - Datapills are converted to {{...}} format correctly
         * - Literal values remain unchanged
         * - Template expressions with datapills work
         * - No cross-contamination between different value types
         */
        test('SetFlowVariables with inline scripts and datapills - no interference', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'set-flow-variables-inline-script-complex.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the first instance (mixed values)
            const mixedInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set variables with mixed value types'
            )
            expect(mixedInstance).toBeDefined()

            const valuesJson = unzipInputArray(mixedInstance.values) as any
            expect(valuesJson.variables).toBeDefined()

            // Test 2.1: Verify DATAPILL is NOT processed as inline script
            const incidentNumberVar = valuesJson.variables.find((v: any) => v.name === 'incidentNumber')
            expect(incidentNumberVar).toBeDefined()
            expect(incidentNumberVar.scriptActive).toBeFalsy() // Should be false or undefined
            expect(incidentNumberVar.value).toContain('{{')
            expect(incidentNumberVar.value).toContain('.current.number}}')
            expect(incidentNumberVar.script).toBeUndefined() // No script object for datapills

            // Test 2.2: Verify DATAPILL (integer) is NOT processed as inline script
            const priorityVar = valuesJson.variables.find((v: any) => v.name === 'priority')
            expect(priorityVar).toBeDefined()
            expect(priorityVar.scriptActive).toBeFalsy()
            expect(priorityVar.value).toContain('{{')
            expect(priorityVar.value).toContain('.current.priority}}')
            expect(priorityVar.script).toBeUndefined()

            // Test 2.3: Verify INLINE SCRIPT is NOT processed as datapill
            const computedPriorityVar = valuesJson.variables.find((v: any) => v.name === 'computedPriority')
            expect(computedPriorityVar).toBeDefined()
            expect(computedPriorityVar.scriptActive).toBe(true)
            expect(computedPriorityVar.script).toBeDefined()
            expect(computedPriorityVar.script.computedPriority.scriptActive).toBe(true)
            expect(computedPriorityVar.script.computedPriority.script).toContain('Math.floor')
            expect(computedPriorityVar.value).toBe('') // Should NOT contain datapill syntax

            // Test 2.4: Verify INLINE SCRIPT with fd_data
            const enrichedDescVar = valuesJson.variables.find((v: any) => v.name === 'enrichedDescription')
            expect(enrichedDescVar).toBeDefined()
            expect(enrichedDescVar.scriptActive).toBe(true)
            expect(enrichedDescVar.script.enrichedDescription.script).toContain(
                'fd_data.trigger.current.short_description'
            )
            expect(enrichedDescVar.value).toBe('') // Should NOT contain datapill syntax

            // Test 2.5: Verify LITERAL is NOT processed as inline script or datapill
            const statusVar = valuesJson.variables.find((v: any) => v.name === 'status')
            expect(statusVar).toBeDefined()
            expect(statusVar.scriptActive).toBeFalsy()
            expect(statusVar.value).toBe('processing')
            expect(statusVar.displayValue).toBe('processing')
            expect(statusVar.script).toBeUndefined()

            // Test 2.6: Verify TEMPLATE EXPRESSION with datapill
            const summaryVar = valuesJson.variables.find((v: any) => v.name === 'summary')
            expect(summaryVar).toBeDefined()
            expect(summaryVar.scriptActive).toBeFalsy()
            expect(summaryVar.value).toContain('Incident')
            expect(summaryVar.value).toContain('{{') // Should have datapill syntax
            expect(summaryVar.value).toContain('}}')
            expect(summaryVar.script).toBeUndefined() // Template expressions are NOT inline scripts

            // Test 2.7: Verify INLINE SCRIPT with complex fd_data access
            const triggerInfoVar = valuesJson.variables.find((v: any) => v.name === 'triggerInfo')
            expect(triggerInfoVar).toBeDefined()
            expect(triggerInfoVar.scriptActive).toBe(true)
            expect(triggerInfoVar.script.triggerInfo.script).toContain('fd_data.trigger.current.sys_class_name')
            expect(triggerInfoVar.script.triggerInfo.script).toContain('fd_data.trigger.current.sys_id')

            // Test 2.8: Verify INLINE SCRIPT with conditional logic
            const dynamicMsgVar = valuesJson.variables.find((v: any) => v.name === 'dynamicMessage')
            expect(dynamicMsgVar).toBeDefined()
            expect(dynamicMsgVar.scriptActive).toBe(true)
            expect(dynamicMsgVar.script.dynamicMessage.script).toContain('var priority')
            expect(dynamicMsgVar.script.dynamicMessage.script).toContain('if (priority')

            // Test 2.9: Verify INLINE SCRIPT returning boolean
            const isHighPriorityVar = valuesJson.variables.find((v: any) => v.name === 'isHighPriority')
            expect(isHighPriorityVar).toBeDefined()
            expect(isHighPriorityVar.scriptActive).toBe(true)
            expect(isHighPriorityVar.script.isHighPriority.script).toContain('fd_data.trigger.current.priority')
            expect(isHighPriorityVar.script.isHighPriority.script).toContain('return')

            // Test 2.10: Verify action output datapill (second instance)
            const actionOutputInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set variables with action output datapills'
            )
            expect(actionOutputInstance).toBeDefined()

            const actionOutputJson = unzipInputArray(actionOutputInstance.values) as any
            const actionOutputVar = actionOutputJson.variables.find((v: any) => v.name === 'incidentNumber')
            expect(actionOutputVar).toBeDefined()
            expect(actionOutputVar.scriptActive).toBeFalsy()
            expect(actionOutputVar.value).toMatch(/^\{\{[0-9a-f-]{36}\..*\}\}$/) // UUID-based datapill
            expect(actionOutputVar.script).toBeUndefined()

            // Test 2.11: Verify flow variable self-reference (third instance)
            const selfRefInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Set variables referencing other flow variables'
            )
            expect(selfRefInstance).toBeDefined()

            const selfRefJson = unzipInputArray(selfRefInstance.values) as any

            // Datapill to flow variable
            const summaryRefVar = selfRefJson.variables.find((v: any) => v.name === 'summary')
            expect(summaryRefVar).toBeDefined()
            expect(summaryRefVar.scriptActive).toBeFalsy()
            expect(summaryRefVar.value).toContain('{{flow_variable.status}}')
            expect(summaryRefVar.script).toBeUndefined()

            // Inline script accessing flow variable via fd_data
            const enrichedRefVar = selfRefJson.variables.find((v: any) => v.name === 'enrichedDescription')
            expect(enrichedRefVar).toBeDefined()
            expect(enrichedRefVar.scriptActive).toBe(true)
            expect(enrichedRefVar.script.enrichedDescription.script).toContain('fd_data.flowVariables.status')
            expect(enrichedRefVar.script.enrichedDescription.script).toContain('fd_data.flowVariables.priority')
        })
    })

    describe('AssignSubflowOutputs with Inline Scripts - flow-logics/fluent to XML', () => {
        /**
         * TEST 2b: Complex Case for AssignSubflowOutputs
         * Similar to setFlowVariables but for subflow outputs
         */
        test('AssignSubflowOutputs with inline scripts and datapills - no interference', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'assign-subflow-outputs-inline-script-complex.now.ts',
                'flow-logics/fluent'
            )

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const assignInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Assign outputs with mixed value types'
            )
            expect(assignInstance).toBeDefined()

            const valuesJson = unzipInputArray(assignInstance.values) as any

            // AssignSubflowOutputs uses 'outputsToAssign' array instead of 'variables'
            expect(valuesJson.outputsToAssign).toBeDefined()
            expect(valuesJson.variables).toEqual([]) // Should be empty for AssignSubflowOutputs

            // Test: Verify DATAPILL is NOT processed as inline script
            const recordIdOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'recordId')
            expect(recordIdOutput).toBeDefined()
            expect(recordIdOutput.scriptActive).toBeFalsy()
            expect(recordIdOutput.value).toMatch(/^\{\{[0-9a-f-]{36}\..*\}\}$/)
            expect(recordIdOutput.script).toBeUndefined()

            // Test: Verify INLINE SCRIPT is NOT processed as datapill
            const processedDataOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'processedData')
            expect(processedDataOutput).toBeDefined()
            expect(processedDataOutput.scriptActive).toBe(true)
            expect(processedDataOutput.script).toBeDefined()
            expect(processedDataOutput.script.processedData.script).toContain('new Date().toISOString()')
            expect(processedDataOutput.value).toBe('')

            // Test: Verify LITERAL
            const statusOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'status')
            expect(statusOutput).toBeDefined()
            expect(statusOutput.scriptActive).toBeFalsy()
            expect(statusOutput.value).toBe('completed')
            expect(statusOutput.script).toBeUndefined()

            // Test: Verify INLINE SCRIPT with fd_data (subflow inputs)
            const enrichedInfoOutput = valuesJson.outputsToAssign.find((o: any) => o.name === 'enrichedInfo')
            expect(enrichedInfoOutput).toBeDefined()
            expect(enrichedInfoOutput.scriptActive).toBe(true)
            expect(enrichedInfoOutput.script.enrichedInfo.script).toContain('fd_data.subflow_inputs.inputNumber')
            expect(enrichedInfoOutput.script.enrichedInfo.script).toContain('fd_data.subflow_inputs.inputPriority')
        })
    })
})
